/**
 * Pure model of an import's metadata lookup record (`adminImportLookups`, one per import project): the file set a run binds,
 * the queries it plans from shared tags, a folder name or submitted text, the bounded candidates it stores, its ranking, its
 * automatic retry schedule and the fence it writes on the import document. No database, no network.
 */
import { createHash } from 'node:crypto';
import type { ObjectId } from 'mongodb';
import type { ImportTagsView } from '../import/adminImportContract';
import { importDraftV2View } from '../import/adminImportDraftCompat';
import type { ImportAsset } from '../import/adminImportMediaTypes';
import type { AdminImportDocument } from '../import/adminImportService';
import { importAssetDurationEvidence, importTagsV2View } from '../import/adminImportTags';
import type { ImportDraftPath } from '../import/adminImportValueState';
import { METADATA_LOOKUP_JOB_LIMITS, type LookupEntityAliases, type MusicBrainzRelease, type MusicBrainzReleaseSummary } from './lookupContract';
import { normalizeMusicBrainzId } from './lookupIdentifiers';
import { planMetadataLookup, type LookupPlan, type LookupPlanInput, type PlannedLookupQuery } from './lookupQueryPlanner';
import { lookupTrackCountPlausible, rankLookupCandidates, type LocalFileEvidence, type LookupPreselection, type RankedLookup } from './lookupRanking';

export type MetadataLookupState = 'queued' | 'running' | 'retrying' | 'complete' | 'unavailable' | 'stopped' | 'superseded';
export type MetadataLookupIssue = 'permissionLost' | 'grantExpired' | 'notConfigured' | 'sourceUnavailable' | 'sourceBusy' | 'fileSetChanged' | 'projectClosed';
/** Which administrator action granted the run: the confirmation that completed the file set, or an explicit request. */
export type MetadataLookupGrantSource = 'upload' | 'reopen' | 'submit' | 'retry' | 'choose';
export type MetadataLookupSubmission = { kind: 'album' | 'song'; text: string };
export type MetadataLookupInput = { trigger: 'tags' | 'folder' | 'submitted'; submitted: MetadataLookupSubmission | null };
/** One manifest slot as a run saw it: the ready upload's intent and bytes, or nulls while the slot has no confirmed file. */
export type LookupFileIdentity = { slotId: string; operationId: string | null; sha256: string | null };
export type StoredLookupCandidate = {
    /** `musicbrainz:<releaseId>`. */
    key: string; source: 'musicbrainz'; releaseId: string;
    basis: PlannedLookupQuery['basis']; summary: MusicBrainzReleaseSummary | null; release: MusicBrainzRelease | null;
    /** Only `fetched` candidates carry a release; every other one is incomplete and unranked. */
    details: 'pending' | 'fetched' | 'missing' | 'failed' | 'omitted';
    /** The release total a recording hit reported for a release without a summary; absent when unknown or stored by an earlier release. */
    reportedTrackCount?: number;
};
export type StoredLookupRanking = RankedLookup & { rankedAt: Date; files: LocalFileEvidence[] };
/** A candidate value left out: control or invisible characters, over a length bound, a failed format, the draft cap, or only placeholder credits. */
export type LookupValueFlag = { path: ImportDraftPath; reason: 'characters' | 'length' | 'format' | 'size' | 'placeholder' };
/** A value resting on the applied candidate, in the draft's stored form; a track value names its local file (manifest slot). */
export type LookupAppliedValue = { path: ImportDraftPath; value: unknown; slotId: string | null };
/**
 * A candidate value that differs from the administrator's own: nothing is preselected until the administrator keeps one.
 * `musicBrainzId` marks a difference only in the MusicBrainz IDs of entries or the label whose names, roles and phrases agree.
 */
export type LookupConflict = { path: ImportDraftPath; lookup: unknown; slotId: string | null; answer: 'mine' | 'lookup' | null; musicBrainzId?: true };
/**
 * The candidate (or none) applied to the import's draft and its evidence: who applied it and how (a preselection, an explicit choice
 * or none), the paths this application wrote, the values that rest on it, its unanswered or answered conflicts and the flagged values.
 * `musicBrainzIds` are the IDs this application supplied that the draft carries after it (an entry by key, the label with entryKey
 * null), which choosing another candidate or none removes again; absent on an application stored before MusicBrainz IDs.
 */
export type LookupApplication = {
    run: number; candidateKey: string | null; releaseId: string | null;
    choice: 'preselected' | 'chosen' | 'none'; basis: LookupPreselection['basis'] | 'chosen' | null;
    actorId: string; operationId: string | null; at: Date;
    paths: ImportDraftPath[]; values: LookupAppliedValue[]; conflicts: LookupConflict[]; flagged: LookupValueFlag[];
    musicBrainzIds?: { entryKey: string | null; musicBrainzId: string }[];
};
export type MetadataLookupRecord = {
    _id: ObjectId; run: number; state: MetadataLookupState; issue: MetadataLookupIssue | null;
    outcome: 'candidates' | 'noRelease' | 'noQuery' | null;
    operationId: string; actorId: string; grantSource: MetadataLookupGrantSource; grantExpiresAt: Date;
    automatic: boolean; input: MetadataLookupInput; queries: PlannedLookupQuery[]; queryIndex: number; phase: 'search' | 'details' | 'aliases' | 'done';
    fileSetDigest: string; files: LookupFileIdentity[];
    /** Failed MusicBrainz attempts of this run; each one schedules an automatic retry until METADATA_LOOKUP_JOB_LIMITS.retryDelaysMs runs out. */
    attempts: { musicbrainz: number }; retryAt: Date | null;
    candidates: StoredLookupCandidate[]; ranking: StoredLookupRanking | null;
    /**
     * The credited artists and labels whose aliases this run looks up after its details (at most 16, lookupRunStep.ts); absent on a
     * record from an earlier release, which completes without them.
     */
    aliases?: LookupEntityAliases[];
    /**
     * Whether every release this run's searches offered that could match was compared: false once a search reported more hits
     * than it returned, the candidate bound left out a release it offered whose reported track count can equal the number of files
     * (or is unknown) or ended the search before a planned non-fallback query, or a planned search was refused (an incomplete
     * candidate that could match makes the ranking partial too). A record without it, from an earlier release, counts as partial
     * when it is re-ranked or resumed. A partial comparison never preselects its only matching group; it offers it.
     */
    searchComplete: boolean;
    /** Written by value application (lookupValueApplication.ts) only; carried over to every later run. */
    applied: LookupApplication | null;
    /**
     * `folderUsed` turns true when a step hands a folder-name query to the worker (stored before the request is sent), so a
     * folder run superseded, stopped or unconfigured before sending anything leaves the allowance for the next automatic run.
     */
    staleSlotIds: string[]; automaticRuns: number; folderUsed: boolean;
    leaseOwner: string | null; leaseUntil: Date | null; createdAt: Date; updatedAt: Date; completedAt: Date | null;
};
/**
 * The import document's fence, never projected: written in the same transaction as every run a trigger or request starts, every
 * state change, every re-rank of stored candidates and every admitted publication approval (which reads it). A trigger that
 * starts nothing, stale marking of a finished run and progress steps do not write it.
 */
export type ImportLookupGate = { fence: number; run: number; state: MetadataLookupState; blocking: boolean };

type LookupSource = Pick<AdminImportDocument, 'manifest' | 'media'>;
const sha256 = (value: unknown) => createHash('sha256').update(JSON.stringify(value)).digest('hex');
const manifestFiles = (doc: Pick<AdminImportDocument, 'manifest'>) => Array.isArray(doc.manifest?.files) ? doc.manifest.files : [];
const readyAsset = (doc: LookupSource, slotId: string): ImportAsset | undefined => (doc.media?.assets ?? []).find(asset => asset.slotId === slotId && asset.state === 'ready');
/** Version-2 evidence of a confirmed file; evidence stored before S8 never reaches lookup, as it never reaches automation. */
const evidence = (asset: ImportAsset | undefined): ImportTagsView | null => {
    const tags = asset ? importTagsV2View(asset.tags) : null;
    return tags?.version === 2 ? tags : null;
};

/**
 * Queued, running and automatically retrying runs block publication. Unanswered ties and conflicts block it too, but they are
 * computed live from the record and the draft (lookupAnswersNeeded), so the gate's `blocking` stays state-only.
 */
export const isBlockingLookupState = (state: unknown) => state === 'queued' || state === 'running' || state === 'retrying';

/** The manifest's audio slots in manifest order with their confirmed files; cover and embedded-artwork slots never count. */
export function importLookupFileSet(doc: LookupSource): { files: LookupFileIdentity[]; complete: boolean; digest: string } {
    const files = manifestFiles(doc).map(file => {
        const asset = readyAsset(doc, file.slotId);
        return { slotId: file.slotId, operationId: asset?.operationId ?? null, sha256: asset?.sha256 ?? null };
    });
    return { files, complete: files.length > 0 && files.every(file => file.operationId !== null && file.sha256 !== null), digest: sha256(files) };
}

/**
 * Bound slots whose confirmed file was replaced or removed since; a slot that became ready later is newly known, not stale. A
 * bound entry this release cannot read (as a later release might store it) is skipped, so it never blocks a file's removal.
 */
export function lookupStaleSlots(bound: readonly unknown[], current: readonly LookupFileIdentity[]): string[] {
    const now = new Map(current.map(file => [file.slotId, file]));
    return bound.filter((file): file is LookupFileIdentity => file !== null && typeof file === 'object'
        && typeof (file as LookupFileIdentity).slotId === 'string' && (file as LookupFileIdentity).operationId != null)
        .filter(file => now.get(file.slotId)?.operationId !== file.operationId || now.get(file.slotId)?.sha256 !== file.sha256)
        .map(file => file.slotId);
}

/** The value every manifest file's version-2 evidence carries, or null when one lacks it, has no evidence or two disagree. */
function shared(all: readonly (ImportTagsView | null)[], pick: (tags: ImportTagsView) => string | null): string | null {
    const values = all.map(tags => tags ? pick(tags) : null);
    return values.length > 0 && values.every(value => value !== null && value === values[0]) ? values[0] : null;
}
const names = (list: readonly string[]) => list.length ? list.join(' / ') : null;

/** Planner input from the confirmed files' shared tags and identifiers; file names and relative paths are never inputs. */
function tagEvidence(doc: LookupSource): Pick<LookupPlanInput, 'tags' | 'identifiers' | 'fileCount'> {
    const files = manifestFiles(doc), all = files.map(file => evidence(readyAsset(doc, file.slotId)));
    const single = files.length === 1 ? all[0] : null;
    return {
        fileCount: files.length,
        // Several files are looked up by their shared album and album-artist tags, never by per-file artists.
        tags: { album: shared(all, tags => tags.album), albumArtist: shared(all, tags => names(tags.albumArtists)),
            title: single?.title ?? null, artist: single ? names(single.artists) : null },
        identifiers: { releaseId: shared(all, tags => tags.identifiers.musicBrainzReleaseId), barcode: shared(all, tags => tags.identifiers.barcode),
            catalogNumber: shared(all, tags => tags.identifiers.catalogNumber), isrc: single?.identifiers.isrc ?? null }
    };
}

/**
 * The queries of one run. Submitted text is planned with the shared tag credits and identifiers. Otherwise the shared tags
 * (a shared album, the title of a one-file import, or a valid shared identifier) are used; only without usable tags, and only
 * once per project, the cleaned name of a chosen folder (some relative path names a folder; files chosen without one have none).
 */
export function planImportLookup(doc: LookupSource, options: { folderAvailable: boolean; submitted?: MetadataLookupSubmission }):
    { input: MetadataLookupInput; plan: LookupPlan } {
    const known = tagEvidence(doc);
    if (options.submitted) {
        const submitted = { kind: options.submitted.kind, text: options.submitted.text };
        return { input: { trigger: 'submitted', submitted }, plan: planMetadataLookup({ ...known, trigger: 'submitted', submitted }) };
    }
    const tags = planMetadataLookup({ ...known, trigger: 'tags', folderName: null });
    const folderChosen = manifestFiles(doc).some(file => typeof file.relativePath === 'string' && file.relativePath.includes('/'));
    if (tags.queries.length || !options.folderAvailable || !folderChosen) return { input: { trigger: 'tags', submitted: null }, plan: tags };
    return { input: { trigger: 'folder', submitted: null }, plan: planMetadataLookup({ trigger: 'folder', folderName: doc.manifest.rootLabel, fileCount: known.fileCount }) };
}

/**
 * Ranking evidence per manifest file in manifest order: the known duration (version-2 milliseconds, else a stored mm:ss with
 * 1-second precision), the current draft's Disc and Track Numbers, the version-2 artist and album-artist tags and identifiers.
 */
export function lookupFileEvidence(doc: Pick<AdminImportDocument, '_id' | 'manifest' | 'media' | 'draft'>): LocalFileEvidence[] {
    const draft = importDraftV2View(doc.draft, doc.manifest, doc._id.toHexString());
    return manifestFiles(doc).map((file, order) => {
        const asset = readyAsset(doc, file.slotId), tags = evidence(asset), duration = asset ? importAssetDurationEvidence(asset) : null;
        const track = draft.tracks.find(item => item.slotId === file.slotId);
        return {
            slotId: file.slotId, order, durationMs: duration?.durationMs ?? null, durationPrecisionMs: duration?.durationPrecisionMs ?? 0,
            discNumber: track?.discNumber ?? null, trackNumber: track?.trackNumber ?? null,
            artistTags: tags ? [...tags.artists, ...tags.albumArtists] : [],
            identifiers: { releaseId: tags?.identifiers.musicBrainzReleaseId ?? null, barcode: tags?.identifiers.barcode ?? null, catalogNumber: tags?.identifiers.catalogNumber ?? null }
        };
    });
}

/** Stored releases drop ISRCs: ranking and value application never read them, and they would only grow the record. */
const compactRelease = (release: MusicBrainzRelease): MusicBrainzRelease => ({
    ...release, media: release.media.map(medium => ({ ...medium, tracks: medium.tracks.map(track => ({ ...track, isrcs: [] })) }))
});
const candidateBytes = (candidates: readonly StoredLookupCandidate[]) => Buffer.byteLength(JSON.stringify(candidates));
/** A fetched release is stored while every candidate together fits the byte budget; otherwise it is omitted and incomplete. */
function withRelease(candidates: StoredLookupCandidate[], index: number, release: MusicBrainzRelease): StoredLookupCandidate[] {
    const next = [...candidates];
    next[index] = { ...candidates[index], release: compactRelease(release), details: 'fetched' };
    if (candidateBytes(next) <= METADATA_LOOKUP_JOB_LIMITS.candidateBytes) return next;
    next[index] = { ...candidates[index], release: null, details: 'omitted' };
    return next;
}

type FoundLookupRelease = { releaseId: string; summary?: MusicBrainzReleaseSummary | null; release?: MusicBrainzRelease | null; trackCount?: number | null };
const reportedCount = (count: unknown) => Number.isSafeInteger(count) && (count as number) > 0 ? count as number : null;
/** The release total a search or lookup reported for a found release or a stored candidate; null when unknown. */
export const lookupReportedTrackCount = (item: { summary?: MusicBrainzReleaseSummary | null; release?: MusicBrainzRelease | null; trackCount?: number | null; reportedTrackCount?: number }) =>
    reportedCount(item.release?.trackCount) ?? reportedCount(item.summary?.trackCount) ?? reportedCount(item.trackCount) ?? reportedCount(item.reportedTrackCount);

/**
 * Adds newly found releases in order, once each by normalized MBID, up to the candidate bound; a release found by ID is fetched.
 * With `fileCount`, releases whose reported track count can match the files are admitted first (a stable partition), so the bound
 * is spent on plausible editions. A recording hit's reported track count is kept, since its release has no summary.
 */
export function mergeLookupCandidates(candidates: readonly StoredLookupCandidate[], found: readonly FoundLookupRelease[],
    basis: PlannedLookupQuery['basis'], fileCount?: number): StoredLookupCandidate[] {
    let next = [...candidates];
    const seen = new Set(next.map(candidate => normalizeMusicBrainzId(candidate.releaseId)));
    const plausible = (item: FoundLookupRelease) => fileCount === undefined || lookupTrackCountPlausible(lookupReportedTrackCount(item), fileCount);
    const ordered = fileCount === undefined ? found : [...found.filter(plausible), ...found.filter(item => !plausible(item))];
    for (const item of ordered) {
        if (next.length >= METADATA_LOOKUP_JOB_LIMITS.candidates) break;
        const releaseId = normalizeMusicBrainzId(item.releaseId);
        if (!releaseId || seen.has(releaseId)) continue;
        seen.add(releaseId);
        const reported = item.summary || item.release ? null : reportedCount(item.trackCount);
        next.push({ key: `musicbrainz:${releaseId}`, source: 'musicbrainz', releaseId, basis, summary: item.summary ?? null, release: null, details: 'pending',
            ...(reported === null ? {} : { reportedTrackCount: reported }) });
        if (item.release) next = withRelease(next, next.length - 1, item.release);
    }
    return next;
}

/**
 * Whether every release a search offered (each valid MBID) that could match `fileCount` files is now a candidate: none was left
 * out by the candidate bound. A left-out release whose reported track count differs cannot match, so it hides nothing.
 */
export function lookupHitsAdmitted(candidates: readonly StoredLookupCandidate[], found: readonly FoundLookupRelease[], fileCount: number): boolean {
    const admitted = new Set(candidates.map(candidate => normalizeMusicBrainzId(candidate.releaseId)));
    return found.every(item => {
        const id = normalizeMusicBrainzId(item.releaseId);
        return !id || admitted.has(id) || !lookupTrackCountPlausible(lookupReportedTrackCount(item), fileCount);
    });
}

/** Stores one candidate's details: a fetched release (compact, within the budget), `missing` for a 404 or `failed`. */
export function recordLookupDetails(candidates: readonly StoredLookupCandidate[], releaseId: string, result: MusicBrainzRelease | null | 'failed'): StoredLookupCandidate[] {
    const id = normalizeMusicBrainzId(releaseId), index = candidates.findIndex(candidate => normalizeMusicBrainzId(candidate.releaseId) === id);
    if (!id || index < 0) return [...candidates];
    if (result === null || result === 'failed') {
        const next = [...candidates];
        next[index] = { ...candidates[index], release: null, details: result === null ? 'missing' : 'failed' };
        return next;
    }
    return withRelease([...candidates], index, result);
}

/**
 * Ranks the stored candidates against the import's current files; an incomplete candidate is never ranked or preselected, and
 * a comparison whose searches were not complete, or with an incomplete candidate that could match, never preselects its only
 * matching group (a release that no longer exists cannot match). `aliases` (fetched artist aliases by ID) let a credited artist
 * agree with an artist tag through an alias.
 */
export function rankLookupRecord(candidates: readonly StoredLookupCandidate[], doc: Pick<AdminImportDocument, '_id' | 'manifest' | 'media' | 'draft'>, now: Date,
    options: { searchComplete: boolean; aliases?: ReadonlyMap<string, readonly string[]> }): StoredLookupRanking {
    const files = lookupFileEvidence(doc);
    const ranked = rankLookupCandidates(candidates.map(candidate => ({ key: candidate.key, source: candidate.source, releaseId: candidate.releaseId,
        summary: candidate.summary, release: candidate.release, reportedTrackCount: reportedCount(candidate.reportedTrackCount), missing: candidate.details === 'missing' })), files,
        { searchComplete: options.searchComplete, aliases: options.aliases });
    return { ...ranked, rankedAt: now, files };
}

/**
 * Ranks the stored candidates while candidates and ranking together stay within `budget` bytes of JSON, measured like the
 * candidate budget (every ranked candidate and group repeats a proposal), so the record stays well under MongoDB's document
 * limit: while over it, the largest fetched release is omitted, incomplete and unranked, and the candidates are ranked again.
 * Every ranking gets the run's `searchComplete`; an omitted release makes the comparison partial too.
 */
export function rankLookupWithinBudget(candidates: readonly StoredLookupCandidate[], doc: Pick<AdminImportDocument, '_id' | 'manifest' | 'media' | 'draft'>, now: Date,
    options: { searchComplete: boolean; budget?: number; aliases?: ReadonlyMap<string, readonly string[]> }): { candidates: StoredLookupCandidate[]; ranking: StoredLookupRanking } {
    const budget = options.budget ?? METADATA_LOOKUP_JOB_LIMITS.recordBytes, searchComplete = options.searchComplete, aliases = options.aliases;
    let kept = [...candidates], ranking = rankLookupRecord(kept, doc, now, { searchComplete, aliases });
    const largest = kept.map((candidate, index) => ({ index, bytes: candidate.release ? candidateBytes([candidate]) : 0 }))
        .filter(entry => entry.bytes > 0).sort((left, right) => right.bytes - left.bytes || left.index - right.index);
    for (const { index } of largest) {
        if (Buffer.byteLength(JSON.stringify({ candidates: kept, ranking })) <= budget) break;
        kept = kept.map((candidate, at): StoredLookupCandidate => at === index ? { ...candidate, release: null, details: 'omitted' } : candidate);
        ranking = rankLookupRecord(kept, doc, now, { searchComplete, aliases });
    }
    return { candidates: kept, ranking };
}

/**
 * When the next automatic retry runs after `failures` failed attempts (30 s, 2 min, 5 min, or a longer Retry-After of at most
 * 60 s; a negative or non-finite one counts as none); null once exhausted. A run's first failure that was a 503/429
 * (`rateLimited`) is a throttled source rather than an outage: it is retried after its Retry-After within 2 to 10 seconds (2 s
 * without one), while the deployment-wide gate still holds the source for a longer Retry-After.
 */
export function lookupRetryAt(failures: number, now: Date, retryAfterMs: number | null, options: { rateLimited?: boolean } = {}): Date | null {
    const delays = METADATA_LOOKUP_JOB_LIMITS.retryDelaysMs;
    if (!Number.isSafeInteger(failures) || failures < 1 || failures > delays.length) return null;
    const given = typeof retryAfterMs === 'number' && Number.isFinite(retryAfterMs) && retryAfterMs >= 0 ? retryAfterMs : null;
    if (options.rateLimited && failures === 1) {
        const { minimum, maximum } = METADATA_LOOKUP_JOB_LIMITS.rateLimitedRetryMs;
        return new Date(now.getTime() + Math.min(Math.max(given ?? minimum, minimum), maximum));
    }
    return new Date(now.getTime() + Math.max(delays[failures - 1], Math.min(given ?? 0, METADATA_LOOKUP_JOB_LIMITS.retryAfterMaximumMs)));
}

/**
 * The next fence: a write that always changes the import document, so any concurrent transaction that also writes that
 * document conflicts and retries. A transaction that only reads it does not conflict: a reader such as the publish gate must
 * also write `lookupGate` (or the document) to be fenced.
 */
export function lookupGateFor(record: Pick<MetadataLookupRecord, 'run' | 'state'>, previous?: ImportLookupGate | null): ImportLookupGate {
    const fence = Number.isSafeInteger(previous?.fence) && previous!.fence >= 0 ? previous!.fence : 0;
    return { fence: fence + 1, run: record.run, state: record.state, blocking: isBlockingLookupState(record.state) };
}

/** UUID-shaped intent of an automatic run, derived like embedded artwork's, so the same run always gets the same ID. */
export function automaticLookupOperationId(importId: string, run: number, digest: string): string {
    const hash = sha256({ importId, run, digest, lookup: 'automatic' });
    return `${hash.slice(0, 8)}-${hash.slice(8, 12)}-4${hash.slice(13, 16)}-8${hash.slice(17, 20)}-${hash.slice(20, 32)}`;
}

/**
 * The next run of an import, replacing the previous run's results. Only the automatic-run count, whether a folder-name query
 * was handed to the worker and the applied values carry over; its searches start complete. A run with no query is complete at
 * once (`noQuery`) and sends nothing.
 */
export function startLookupRun(previous: MetadataLookupRecord | null, init: {
    importId: ObjectId; actorId: string; grantSource: MetadataLookupGrantSource; operationId: string; automatic: boolean;
    input: MetadataLookupInput; queries: PlannedLookupQuery[];
    fileSet: { files: LookupFileIdentity[]; digest: string }; now: Date;
}): MetadataLookupRecord {
    const { now } = init, searching = init.queries.length > 0;
    return {
        _id: init.importId, run: (Number.isSafeInteger(previous?.run) ? previous!.run : 0) + 1,
        state: searching ? 'queued' : 'complete', issue: null, outcome: searching ? null : 'noQuery',
        operationId: init.operationId, actorId: init.actorId, grantSource: init.grantSource, grantExpiresAt: new Date(now.getTime() + METADATA_LOOKUP_JOB_LIMITS.grantMs),
        automatic: init.automatic, input: { trigger: init.input.trigger, submitted: init.input.submitted ? { ...init.input.submitted } : null },
        queries: init.queries.map(query => structuredClone(query)), queryIndex: 0, phase: searching ? 'search' : 'done',
        fileSetDigest: init.fileSet.digest, files: init.fileSet.files.map(file => ({ ...file })), attempts: { musicbrainz: 0 }, retryAt: null,
        candidates: [], ranking: null, aliases: [], searchComplete: true, applied: previous?.applied ?? null, staleSlotIds: [],
        automaticRuns: (Number.isSafeInteger(previous?.automaticRuns) ? previous!.automaticRuns : 0) + (init.automatic ? 1 : 0),
        folderUsed: previous?.folderUsed === true,
        leaseOwner: null, leaseUntil: null, createdAt: now, updatedAt: now, completedAt: searching ? null : now
    };
}

/** The names of a record's fetched alias lookups by MusicBrainz ID; a record without aliases (or a malformed entry) gives none. */
export function lookupFetchedAliases(record: Pick<MetadataLookupRecord, 'aliases'> | null | undefined): Map<string, string[]> {
    const map = new Map<string, string[]>();
    for (const entry of Array.isArray(record?.aliases) ? record!.aliases : []) {
        const id = entry && typeof entry === 'object' && entry.state === 'fetched' && Array.isArray(entry.names) ? normalizeMusicBrainzId(entry.id) : null;
        if (id && !map.has(id)) map.set(id, entry.names.filter((name): name is string => typeof name === 'string').slice(0, METADATA_LOOKUP_JOB_LIMITS.aliasNames));
    }
    return map;
}

/** Moves a record's grant to another administrator's action (choosing a candidate); the run itself is unchanged. */
export function refreshLookupGrant(record: MetadataLookupRecord, actorId: string, source: MetadataLookupGrantSource, now: Date): MetadataLookupRecord {
    return { ...record, actorId, grantSource: source, grantExpiresAt: new Date(now.getTime() + METADATA_LOOKUP_JOB_LIMITS.grantMs), updatedAt: now };
}
